def legacy_invoice_total(lines, region):
    total = 0
    for qty, price in lines:
        line = round(qty * price, 2)
        if region == 'EU':
            line = round(line * 1.2, 2)
        elif region == 'US' and qty > 10:
            line = round(line * 0.95, 2)
        total += line
    return round(total, 2)
